#!/usr/bin/env python3
"""Write module/src/modules/anti_exfil/tests_vectors.h from vectors/bip-anti-exfil.json
(valid and forced-hash cases, copied verbatim as hex strings). Prints the hash of
the vector file used."""
import hashlib, json, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[1]
raw = (ROOT / "vectors/bip-anti-exfil.json").read_bytes()
d = json.loads(raw)
out = ["/* Generated by c/gen_test_vectors.py from vectors/bip-anti-exfil.json,",
       " * sha256 %s. Do not edit. */" % hashlib.sha256(raw).hexdigest(),
       "#ifndef SECP256K1_MODULE_ANTI_EXFIL_TESTS_VECTORS_H",
       "#define SECP256K1_MODULE_ANTI_EXFIL_TESTS_VECTORS_H", "",
       "/* m is \"@long\" where it is over 500 hex characters (C89 string limit): then it is the 32 hashes of seed/m/j, joined. */",
       "typedef struct { const char *id, *seed, *sk, *m, *rho, *pk, *hc, *r0, *sig; } anti_exfil_test_valid;",
       "typedef struct { const char *id, *tag, *output, *extra, *expected, *ops, *sk, *m, *rho, *hc, *pk, *r0, *sig; } anti_exfil_test_forced;", ""]
def q(s):
    # C89 guarantees string literals of 509 characters; split longer ones.
    parts = [s[i:i + 400] for i in range(0, len(s), 400)] or [""]
    return " ".join('"%s"' % x for x in parts)
for key, name in (("bip340", "schnorr"), ("ecdsa", "ecdsa")):
    out.append("static const anti_exfil_test_valid anti_exfil_vectors_%s_valid[] = {" % name)
    for c in d[key]["valid"]:
        out.append("    {%s}," % ", ".join(q(x) for x in (c["id"], c["seed"], c["sk"], ("@long" if len(c["m"]) > 500 else c["m"]), c["rho"], c["pk"], c["hc"], c["R0_bytes"], c["sig"])))
    out.append("};")
    out.append("static const anti_exfil_test_forced anti_exfil_vectors_%s_forced[] = {" % name)
    for c in d[key]["forced_hash"]:
        g = lambda k: c.get(k, "")
        out.append("    {%s}," % ", ".join(q(x) for x in (c["id"], c["forced_hash"]["tag"], c["forced_hash"]["output"],
                   ",".join("%s:%s" % (e["tag"], e["output"]) for e in c.get("additional_forced_hashes", [])), c["expected"],
                   ",".join(c["operations"]), g("sk"), g("m"), g("rho"), g("hc"), g("pk"), g("R0_bytes"), g("sig"))))
    out.append("};")
out += ["", "#endif", ""]
(ROOT / "c/module/src/modules/anti_exfil/tests_vectors.h").write_text("\n".join(out))
print("sha256", hashlib.sha256(raw).hexdigest())
